package com.fitnutri.backend.records.workout;
import com.fitnutri.backend.common.CurrentUserService;
import org.springframework.http.*;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v2/exercise")
public class ExerciseEntryV2Controller {
 private final WorkoutEstimateService estimates;private final CurrentUserService current;private final ExerciseEntryV2Service entries;private final WorkoutCorrectionPreviewService corrections;private final WorkoutMutationService mutations;private final ExerciseEntryReadService reads;
 public ExerciseEntryV2Controller(WorkoutEstimateService estimates,CurrentUserService current,ExerciseEntryV2Service entries,WorkoutCorrectionPreviewService corrections,WorkoutMutationService mutations,ExerciseEntryReadService reads){this.estimates=estimates;this.current=current;this.entries=entries;this.corrections=corrections;this.mutations=mutations;this.reads=reads;}
 @PostMapping("/preview") public ResponseEntity<WorkoutEstimateService.Response> preview(@RequestBody ExerciseEntryInputs.PreviewRequest request,Authentication auth){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(estimates.previewNew(current.requireGeneralUser(auth).getId(),request));}
 @PostMapping("/entries") public ResponseEntity<com.fitnutri.backend.submission.SubmissionReceiptV2Response> create(@RequestBody ExerciseEntryInputs.CreateRequest request,Authentication auth){var result=entries.createEntryV2(current.requireGeneralUser(auth).getId(),request);return ResponseEntity.status(result.replayed()?HttpStatus.OK:HttpStatus.CREATED).cacheControl(CacheControl.noStore()).header("Idempotent-Replay",Boolean.toString(result.replayed())).body(result);}
 @PostMapping("/entries/{kind}/{id}/preview") public ResponseEntity<WorkoutEstimateService.Response> correction(@PathVariable String kind,@PathVariable long id,@RequestBody ExerciseEntryInputs.CorrectionRequest request,Authentication auth){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(corrections.previewOwnedRoot(current.requireGeneralUser(auth).getId(),kind,id,request));}
 @PutMapping("/entries/{kind}/{id}") public ResponseEntity<ExerciseEntryReadService.Root> update(@PathVariable String kind,@PathVariable long id,@RequestBody ExerciseEntryInputs.UpdateRequest request,Authentication auth){var owner=current.requireGeneralUser(auth).getId();mutations.updateOwnedRoot(owner,kind,id,request);return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(reads.getOwnedRoot(owner,kind,id));}
 @DeleteMapping("/entries/{kind}/{id}") public ResponseEntity<Void> delete(@PathVariable String kind,@PathVariable long id,@RequestParam Long expectedVersion,Authentication auth){mutations.softDeleteOwnedRoot(current.requireGeneralUser(auth).getId(),kind,id,expectedVersion);return ResponseEntity.noContent().cacheControl(CacheControl.noStore()).build();}
 @ExceptionHandler(ExerciseCalculationChangedV2Exception.class) public ResponseEntity<ExerciseCalculationChangedV2Response> changed(ExerciseCalculationChangedV2Exception error,jakarta.servlet.http.HttpServletRequest request){return ResponseEntity.status(HttpStatus.CONFLICT).cacheControl(CacheControl.noStore()).body(ExerciseCalculationChangedV2Response.from(com.fitnutri.backend.common.ApiError.create(409,error.code(),error.getMessage(),request,java.util.List.of(),false),error.currentPreview()));}
}
